import * as THREE from 'three/webgpu';
import { texture, uv, vec4, float, uniform } from 'three/tsl';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'features-card-1-label';
  group.position.set(-3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 1.6;
  const height = 1.0;

  const geometry = new THREE.PlaneGeometry(width, height);

  const map = ctx.textureLoader.load('/prism-mock/home/nodes/cta-hero-isolated.png');
  map.colorSpace = THREE.SRGBColorSpace;

  const grainAmount = uniform(0.035);

  const material = new THREE.MeshBasicNodeMaterial();
  const uvNode = uv();
  const texColor = texture(map, uvNode);

  // engineered gradient overlay using surface/ink tones, plus subtle procedural grain
  const gradTop = vec4(0.09, 0.09, 0.11, 1.0); // surface #0b0b10 approx
  const gradBottom = vec4(0.086, 0.086, 0.114, 1.0); // ink #16161d approx
  const gradMix = gradTop.mul(float(1.0).sub(uvNode.y)).add(gradBottom.mul(uvNode.y));

  const noise = uvNode.x.mul(12.9898).add(uvNode.y.mul(78.233)).sin().mul(43758.5453).fract();
  const grain = noise.sub(0.5).mul(grainAmount);

  const finalColor = texColor.rgb.mul(0.85).add(gradMix.rgb.mul(0.15)).add(grain);
  material.colorNode = vec4(finalColor, texColor.a);

  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'features-card-1-label-plane';
  group.add(plane);

  const textMesh = createTextMesh({
    text: 'Features 1',
    font: 'Lora',
    weight: 400,
    role: 'headline',
    sizeEm: 0.34,
    color: '#e8ecf2',
    fontAtlas: ctx.fontAtlas,
    maxWidth: width * 0.85,
    align: 'center',
  });
  textMesh.position.set(0, 0, 0.01);
  group.add(textMesh);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map) map.dispose();
    if (textMesh.geometry) textMesh.geometry.dispose();
    if (textMesh.material) {
      if (Array.isArray(textMesh.material)) {
        textMesh.material.forEach((m) => m.dispose());
      } else {
        textMesh.material.dispose();
      }
    }
  };

  return group;
}
